// A random id for this visitor. The server uses it to remember who is logged in.
// It lives in localStorage so it survives a page refresh; otherwise a new token
// would be made on every load and the server would not recognise us.
const TOKEN_KEY = 'portfolio-session-token';

function loadSessionToken() {
  try {
    const saved = localStorage.getItem(TOKEN_KEY);
    if (saved) {
      return saved;
    }
  } catch (error) {
    // Storage can be unavailable (private mode); fall back to a fresh token.
  }
  const token = Math.random().toString(36).slice(2);
  try {
    localStorage.setItem(TOKEN_KEY, token);
  } catch (error) {
    // Not stored, so a refresh will log us out. Nothing better to do here.
  }
  return token;
}

const sessionToken = loadSessionToken();

