const crypto = require('crypto');
const path = require('path');
const express = require('express');

const app = express();
const PORT = process.env.PORT || 3000;

// The accounts that can log in. (Just one for now.)
const users = {
  alex: 'portfolio123',
};

// Everyone who is logged in right now: session token -> username.
const sessions = {};

// Each user's projects, kept apart from the session so logging out and back in
// (or logging in from another browser) still finds them.
const projects = {};

let nextProjectId = 1;

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// The username behind this request's session token, or undefined. No token, no user.
function getUsername(req) {
  return sessions[req.get('X-Session-Token')];
}

function projectsFor(username) {
  if (!projects[username]) {
    projects[username] = [];
  }
  return projects[username];
}

app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  if (!users[username] || users[username] !== password) {
    return res.status(401).json({ error: 'Wrong username or password' });
  }

  // The server mints the token, so it is unpredictable and cannot be chosen by
  // whoever is logging in. Each login gets its own token.
  const token = crypto.randomUUID();
  sessions[token] = username;
  res.json({ token, username, projects: projectsFor(username) });
});

app.get('/api/me', (req, res) => {
  const username = getUsername(req);
  if (!username) {
    return res.status(401).json({ error: 'Not logged in' });
  }
  res.json({ username, projects: projectsFor(username) });
});

app.post('/api/projects', (req, res) => {
  const username = getUsername(req);
  if (!username) {
    return res.status(401).json({ error: 'Not logged in' });
  }

  const { title, description, link } = req.body;
  if (!title) {
    return res.status(400).json({ error: 'A project needs a title' });
  }

  const project = {
    id: nextProjectId++,
    title,
    description: description || '',
    link: link || '',
  };
  projectsFor(username).push(project);
  res.status(201).json(project);
});

app.post('/api/logout', (req, res) => {
  delete sessions[req.get('X-Session-Token')];
  res.json({ ok: true });
});

app.listen(PORT, () => {
  console.log(`Portfolio running at http://localhost:${PORT}`);
});

